 for(let c of this.clouds){c.t+=dt;for(let e of this.combatTargets())if(e.hp>0&&dist(e,c)<c.r+e.r)this.hit(e,c.dps*dt,'gas');}this.clouds=this.clouds.filter(c=>c.t<c.life);
