 for(let d of this.drops){if(d.heal){if(d.life!=null){d.life-=dt;if(d.life<=0){d.taken=true;continue;}}if(p.hp>p.max-8)continue;}let r=dist(d,p);if(r<100+this.passives.magnet*35+(this.perks.pickup||0)*20||this.magnetTime>0&&!d.chest&&!d.heal&&!d.coffee){d.x+=(p.x-d.x)/Math.max(1,r)*300*dt;d.y+=(p.y-d.y)/Math.max(1,r)*300*dt;}if(r<23){d.taken=true;if(d.chest){this.pendingBriefcases++;}else if(d.magnet){this.magnetTime=5;this.event('upgrade','CASH SWEEP · COLLECT IT ALL');}else if(d.coffee){this.caffeine=8;this.event('coffee','CAFFEINE RUSH · 8s OF SPEED + RAPID FIRE');}else if(d.heal){p.hp=Math.min(p.max,p.hp+16);this.healCount++;this.event('heal',''); /* Herman's relieved ahh */}else{this.tokens+=d.value;this.xp+=d.value*(1+this.passives.magnet*.1);if(!this.events.some(e=>e.type==='pickup'))this.event('pickup','');}}}this.drops=this.drops.filter(d=>!d.taken);if(this.drops.length>500){let loose=this.drops.filter(d=>!d.heal&&!d.chest&&!d.magnet&&!d.coffee);if(loose.length>1){loose[1].value+=loose[0].value;this.drops.splice(this.drops.indexOf(loose[0]),1);}}
